def smallest_change(arr):
    def min_changes_to_palindrome(subarr):
        n = len(subarr)
        dp = [[0] * n for _ in range(n)]

        for gap in range(1, n):
            l = 0
            for h in range(gap, n):
                if subarr[l] == subarr[h]:
                    dp[l][h] = dp[l + 1][h - 1]
                else:
                    dp[l][h] = min(dp[l][h - 1], dp[l + 1][h]) + 1
