def check_consistent_order(lst):
    if not lst:
        return "List is empty"
    if len(lst) == 1:
        return "List has only one element"

    increasing = all(lst[i] < lst[i+1] for i in range(len(lst)-1))
    decreasing = all(lst[i] > lst[i+1] for i in range(len(lst)-1))

    if increasing:
        return "List is consistently increasing"
    elif decreasing:
        return "List is consistently decreasing"
    else:
        return "List is neither consistently increasing nor decreasing"

